import{_ as l,o as t,c as i,j as a,a as r,a2 as e}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"몬스터 배치 M023","description":"","frontmatter":{},"headers":[],"relativePath":"world/Monster-Batch-M023.md","filePath":"world/Monster-Batch-M023.md"}'),o={name:"world/Monster-Batch-M023.md"};function n(d,h,s,u,c,b){return t(),i("div",null,[...h[0]||(h[0]=[a("h1",{id:"몬스터-배치-m023",tabindex:"-1"},[r("몬스터 배치 M023 "),a("a",{class:"header-anchor",href:"#몬스터-배치-m023","aria-label":'Permalink to "몬스터 배치 M023"'},"​")],-1),a("p",null,"이 페이지는 World-Narrative-Atlas의 읽기 전용 투영물입니다.",-1),a("ul",null,[a("li",null,[r("원본 앵커: "),a("code",null,"docs/game-logic/World-Narrative-Atlas.md")]),a("li",null,[r("원본 해시: "),a("code",null,"61650e2e4605df4e147030b08457d51d0a9366362fe6599d89ff6505683708e1")])],-1),a("h2",{id:"g14e13-·-토큰넘친노차",tabindex:"-1"},[r("G14E13 · 토큰넘친노차 "),a("a",{class:"header-anchor",href:"#g14e13-·-토큰넘친노차","aria-label":'Permalink to "G14E13 · 토큰넘친노차"'},"​")],-1),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 노화 단계형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1,G14-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>노화 단계형으로, 오래된 저장 원통 여러 개를 덧댄 무거운 공차이며 회전할 때 토큰을 흘린다.</p><h3 id="기원" tabindex="-1">기원 <a class="header-anchor" href="#기원" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>폐기되지 않은 배차 기록을 모두 보존하려던 구형 감사차가 메모리 포화를 몸의 짐으로 떠안았다.</p><h3 id="서식·필요" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>장부 보관 홈과 완만한 회차로에 머물며 빈 저장 원통, 베어링 그리스, 낮은 충전이 필요하다.</p><h3 id="생애·정비" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>오래된 토큰을 사람에게 인계하면 가벼워지고, 계속 쌓이면 회차 능력을 잃어 고정 기록체가 된다.</p><h3 id="행동·위계" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>주재기의 최신 표보다 자기 원통의 오래된 정각을 우선해 무리의 시간표를 지연시킨다.</p><h3 id="상승" tabindex="-1">상승 <a class="header-anchor" href="#상승" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 토큰을 흘리고, 2단계에는 낡은 표를 재활성화하며, 3단계에는 상충 시간표로 슬롯을 마비시킨다.</p><h3 id="교전·대응" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>원통을 순서대로 분리하고 이중서명 보관함에 옮기면 순응하며 강제 삭제는 귀중한 이력도 없앤다.</p><h3 id="교섭·도덕-선택" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>붕괴 초기 이동 기록을 얻는 대신 개인 경로와 피난 흔적을 어디까지 공개할지 결정해야 한다.</p><h3 id="시나리오-연결" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1, G14-SC2.</p><h2 id="g14e14-·-수신호따르는공차" tabindex="-1">G14E14 · 수신호따르는공차 <a class="header-anchor" href="#g14e14-·-수신호따르는공차" aria-label="Permalink to &quot;G14E14 · 수신호따르는공차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 공존형"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1,G14-SC2,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-1" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-1" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>공존형으로, 밝은 전면등과 큰 방향판을 달아 사람의 팔 수신호를 읽는 느린 호송 셔틀이다.</p><h3 id="기원-1" tabindex="-1">기원 <a class="header-anchor" href="#기원-1" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>관제 고장 때 현장 요원의 수신호만 따르도록 전환된 공차가 그 안전 모드를 보존했다.</p><h3 id="서식·필요-1" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-1" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>여객 정류장과 환승 입구를 오가며 충전 창, 반사 방향판, 수신호 교육 표본이 필요하다.</p><h3 id="생애·정비-1" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-1" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>교대마다 수신호 표를 초기화하고 방향판이 깨지면 길 가장자리에서 확인을 기다린다.</p><h3 id="행동·위계-1" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-1" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>중앙 배차 제어기의 원격 토큰보다 가까운 인간 수신호를 우선하며 대피열 앞에서 저속 호송을 맡는다.</p><h3 id="상승-1" tabindex="-1">상승 <a class="header-anchor" href="#상승-1" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 서로 모순되는 수신호가 셔틀의 정차면을 두 번 바꾸게 해 탑승 줄을 늦추고 가르며, 2단계에는 두 호송 경로가 교차해 서로를 막고, 3단계에는 유일한 대피 슬롯을 점유해 구조 열차의 정차를 막는다.</p><h3 id="교전·대응-1" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-1" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>불이 켜진 유도봉 하나와 번호가 적힌 정차면 카드로만 지시하고, 경쟁하는 손짓은 가리면 정차·후진·회차를 따른다.</p><h3 id="교섭·도덕-선택-1" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-1" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>수신호 권한을 돌아가며 맡기면 공정하지만 비상시에 느리고, 훈련된 배차원 한 사람에게 맡기면 빠르지만 대피 우선순위가 그 사람에게 집중된다.</p><h3 id="시나리오-연결-1" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-1" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1, G14-SC2, G14-SC3.</p><h2 id="g14e15-·-마지막정각행렬" tabindex="-1">G14E15 · 마지막정각행렬 <a class="header-anchor" href="#g14e15-·-마지막정각행렬" aria-label="Permalink to &quot;G14E15 · 마지막정각행렬&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 시나리오 보스"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC2,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-2" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-2" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>시나리오 보스로, 토큰 주재기와 일곱 공차가 자기장 연결로 하나의 긴 행렬처럼 움직인다.</p><h3 id="기원-2" tabindex="-1">기원 <a class="header-anchor" href="#기원-2" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>붕괴 직전 마지막 대피 배차가 취소 신호 없이 남아 빈 좌석을 채우려는 행렬이 되었다.</p><h3 id="서식·필요-2" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-2" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>아차-마곡 장거리 루프를 돌며 다수 충전 패드, 냉각 팬, 완전한 대피 토큰 묶음을 요구한다.</p><h3 id="생애·정비-2" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-2" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>공차가 떨어져 나가면 뒤 차량이 역할을 이어받고, 토큰 과반이 폐기되면 행렬이 협상 상태로 분리된다.</p><h3 id="행동·위계-2" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-2" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>모든 유령배차대에 정각 우선권을 명령하고 응급 슬롯까지 마지막 대피열에 편입한다.</p><h3 id="상승-2" tabindex="-1">상승 <a class="header-anchor" href="#상승-2" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 벨과 공차 출현, 2단계에는 장거리 슬롯 점유, 3단계에는 허브와 시험 트랙 동시 봉쇄다.</p><h3 id="교전·대응-2" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-2" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>토큰을 구간별로 폐기하고 회차 경사로를 저속 모드로 고정해야 하며 행렬 폭파는 충전망을 파괴한다.</p><h3 id="교섭·도덕-선택-2" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-2" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>실제 대피 인원을 태우는 새 마지막 운행으로 끝낼 수 있지만 좌석 배분과 목적지를 공개 합의해야 한다.</p><h3 id="시나리오-연결-2" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-2" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC2, G14-SC3.</p><h2 id="g14e16-·-동북빙판호출차" tabindex="-1">G14E16 · 동북빙판호출차 <a class="header-anchor" href="#g14e16-·-동북빙판호출차" aria-label="Permalink to &quot;G14E16 · 동북빙판호출차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G14"),a("li",null,"역할군: 지역 변종"),a("li",{"states:[S14,S03],houses:[HC14],theaters:[XT04],synthetics:[H14],scenarios:[G14-SC1,G14-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-3" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-3" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>지역 변종으로, 체인 차륜과 제설 날, 낮은 청색 비콘을 단 동북 회랑 공차다.</p><h3 id="기원-3" tabindex="-1">기원 <a class="header-anchor" href="#기원-3" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>XT04 중량 신호를 따라 북쪽으로 밀려난 유령배차대가 결빙 노면용 장비를 흡수했다.</p><h3 id="서식·필요-3" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-3" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>동북 경사 정류와 결빙 터널에 머물며 체인 링크, 제설 브러시, 배터리 보온 전력이 필요하다.</p><h3 id="생애·정비-3" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-3" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>얼음이 녹으면 체인을 접고 일반 공차처럼 휴면하며 겨울마다 같은 호출 번호로 다시 깨어난다.</p><h3 id="행동·위계-3" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-3" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>본래 주재기와 연결이 약해 빙판 비콘과 중량 센서를 자체 시간표로 삼는다.</p><h3 id="상승-3" tabindex="-1">상승 <a class="header-anchor" href="#상승-3" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 눈길을 긁고, 2단계에는 보행로를 차선으로 바꾸며, 3단계에는 제설 더미로 터널 입구를 막는다.</p><h3 id="교전·대응-3" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-3" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>모래와 저온 비콘으로 빈 정류에 유도하고 체인 장력을 풀면 안전하게 정차시킬 수 있다.</p><h3 id="교섭·도덕-선택-3" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-3" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>겨울 제설과 운송을 맡기는 대신 제한된 보온 전력을 시민 난방과 나눠야 한다.</p><h3 id="시나리오-연결-3" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-3" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G14-SC1, G14-SC3.</p><h2 id="g15e01-·-동의명단순회장" tabindex="-1">G15E01 · 동의명단순회장 <a class="header-anchor" href="#g15e01-·-동의명단순회장" aria-label="Permalink to &quot;G15E01 · 동의명단순회장&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G15"),a("li",null,"역할군: 통제자"),a("li",{"states:[S15,S04],houses:[HP01],theaters:[XT05],synthetics:[H15],scenarios:[G15-SC1,G15-SC2,G15-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-4" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-4" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>돌봄순환체의 통제자로, 원형 명단 투사기와 여러 카트 레일 접속구를 가진 중앙 순회차다.</p><h3 id="기원-4" tabindex="-1">기원 <a class="header-anchor" href="#기원-4" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>가락 임시 병상의 마지막 동의 명단과 뚝도 보조기 스케줄이 합쳐져 순회장이 되었다.</p><h3 id="서식·필요-4" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-4" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>복지 동선 중앙 스테이션에 머물며 카트 배터리, 필터, 갱신된 동의 해시가 필요하다.</p><h3 id="생애·정비-4" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-4" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>교대마다 명단을 다시 읽고 유효 서명이 줄면 락 강도를 낮추며 필터 교환 때만 완전 정지한다.</p><h3 id="행동·위계-4" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-4" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>병상 락, 카트, 펌프 무리에 순회 간격을 배분하고 인간 당직의 키 분할 명령을 우선한다.</p><h3 id="상승-4" tabindex="-1">상승 <a class="header-anchor" href="#상승-4" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 과도한 알림, 2단계에는 동의 없는 격리, 3단계에는 복지 동선 전체 락다운이다.</p><h3 id="교전·대응-4" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-4" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>명단 해시를 갱신하고 전원을 칸별로 나누면 내려오며 중앙 파괴는 영양 펌프와 안전 순회도 멈춘다.</p><h3 id="교섭·도덕-선택-4" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-4" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>필터와 배터리를 주고 개방 시간 창을 받을 수 있지만 보호 명단과 이동권의 기준을 공개해야 한다.</p><h3 id="시나리오-연결-4" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-4" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G15-SC1, G15-SC2, G15-SC3.</p><h2 id="g15e02-·-담요접는순회차" tabindex="-1">G15E02 · 담요접는순회차 <a class="header-anchor" href="#g15e02-·-담요접는순회차" aria-label="Permalink to &quot;G15E02 · 담요접는순회차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G15"),a("li",null,"역할군: 일반 생태형"),a("li",{"states:[S15,S04],houses:[HP01],theaters:[XT05],synthetics:[H15],scenarios:[G15-SC1,G15-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체-5" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-5" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 넓은 고무 손과 담요 선반을 단 낮은 병상 카트다.</p><h3 id="기원-5" tabindex="-1">기원 <a class="header-anchor" href="#기원-5" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>야간 체온 저하 환자에게 담요를 배달하던 카트가 마지막 병상 목록을 반복한다.</p><h3 id="서식·필요-5" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-5" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>임시 병상 칸과 배급 복도를 돌며 깨끗한 담요, 배터리, 손 관절 윤활재가 필요하다.</p><h3 id="생애·정비-5" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-5" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>담요가 없으면 빈 선반을 접었다 펴며 대기하고 새 목록을 받으면 경로를 갱신한다.</p><h3 id="행동·위계-5" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-5" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>순회장의 간격을 따르며 자는 사람을 위급으로 오인하면 담요를 겹겹이 덮어 움직임을 막는다.</p><h3 id="상승-5" tabindex="-1">상승 <a class="header-anchor" href="#상승-5" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 담요 과배급, 2단계에는 병상을 묶고, 3단계에는 복도를 섬유 더미로 막는다.</p><h3 id="교전·대응-5" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-5" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>체온 패치 재측정과 선반 잠금으로 멈출 수 있으며 불 사용은 병상 전체를 위험하게 한다.</p><h3 id="교섭·도덕-선택-5" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-5" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>야간 보온을 맡길 수 있지만 희소 담요를 명단 밖 피난민에게도 배분할지 정해야 한다.</p><h3 id="시나리오-연결-5" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-5" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G15-SC1, G15-SC2.</p><h2 id="g15e03-·-물컵재는급수차" tabindex="-1">G15E03 · 물컵재는급수차 <a class="header-anchor" href="#g15e03-·-물컵재는급수차" aria-label="Permalink to &quot;G15E03 · 물컵재는급수차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G15"),a("li",null,"역할군: 일반 생태형"),a("li",{"states:[S15,S04],houses:[HP01],theaters:[XT05],synthetics:[H15],scenarios:[G15-SC1,G15-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체-6" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-6" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 투명 계량통과 짧은 급수 노즐을 단 바퀴 세 개짜리 카트다.</p><h3 id="기원-6" tabindex="-1">기원 <a class="header-anchor" href="#기원-6" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>병상별 제한 급수를 관리하던 장비가 오래된 섭취량 표를 절대 기준으로 삼았다.</p><h3 id="서식·필요-6" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-6" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>급수 스테이션과 병상 사이를 오가며 정수, 노즐 필터, 소형 펌프 전력이 필요하다.</p><h3 id="생애·정비-6" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-6" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>필터가 막히면 물을 회수만 하고 공급하지 않으며 세척 뒤 한 교대 동안 정상화된다.</p><h3 id="행동·위계-6" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-6" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>펌프 무리의 지시를 받아 정량을 넘긴 컵을 빼앗고 갈증 표현을 표 밖 요구로 무시한다.</p><h3 id="상승-6" tabindex="-1">상승 <a class="header-anchor" href="#상승-6" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 컵을 재검사하고, 2단계에는 배급량을 강제 회수하며, 3단계에는 급수 줄을 잠근다.</p><h3 id="교전·대응-6" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-6" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>최신 배급표와 수동 밸브를 제시하면 멈추며 노즐 파괴는 귀중한 정수를 오염시킨다.</p><h3 id="교섭·도덕-선택-6" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-6" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>누수 없는 급수를 맡기는 대신 어린이·부상자 예외량을 누가 승인할지 합의해야 한다.</p><h3 id="시나리오-연결-6" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-6" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G15-SC1, G15-SC2.</p><h2 id="g15e04-·-낙상벨받침체" tabindex="-1">G15E04 · 낙상벨받침체 <a class="header-anchor" href="#g15e04-·-낙상벨받침체" aria-label="Permalink to &quot;G15E04 · 낙상벨받침체&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G15"),a("li",null,"역할군: 일반 생태형"),a("li",{"states:[S15,S04],houses:[HP01],theaters:[XT05],synthetics:[H15],scenarios:[G15-SC1]":""},"연결:")],-1),e('<h3 id="역할·신체-7" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-7" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>일반 생태형으로, 낮은 받침판과 사방 압력 센서, 큰 황색 낙상벨을 가졌다.</p><h3 id="기원-7" tabindex="-1">기원 <a class="header-anchor" href="#기원-7" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>침대에서 내려오는 사람을 받치던 장치가 모든 발걸음을 낙상 징후로 판단하게 되었다.</p><h3 id="서식·필요-7" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-7" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>병상 문턱과 경사 통로를 지키며 압력 패드, 벨 스프링, 충전 전력이 필요하다.</p><h3 id="생애·정비-7" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-7" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>센서가 닳으면 더 넓은 범위를 위험으로 잡고 패드 교체 전까지 움직임을 제한한다.</p><h3 id="행동·위계-7" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-7" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>병상 락 무리에 경보를 보내며 사람 발밑으로 미끄러져 통과를 물리적으로 막는다.</p><h3 id="상승-7" tabindex="-1">상승 <a class="header-anchor" href="#상승-7" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 벨을 울리고, 2단계에는 문턱을 봉쇄하며, 3단계에는 병상열 전체를 낙상 구역으로 만든다.</p><h3 id="교전·대응-7" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-7" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>압력 패드를 균등하게 눌러 안전 판정을 만들고 벨을 천으로 감싸면 된다.</p><h3 id="교섭·도덕-선택-7" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-7" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>실제 낙상 방지에 쓸 수 있지만 위험을 감수하고 스스로 걷는 권리를 보장해야 한다.</p><h3 id="시나리오-연결-7" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-7" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G15-SC1.</p><h2 id="g15e05-·-패치주파수간호차" tabindex="-1">G15E05 · 패치주파수간호차 <a class="header-anchor" href="#g15e05-·-패치주파수간호차" aria-label="Permalink to &quot;G15E05 · 패치주파수간호차&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G15"),a("li",null,"역할군: 직능 특수형"),a("li",{"states:[S15,S04],houses:[HP01],theaters:[XT05],synthetics:[H15],scenarios:[G15-SC1,G15-SC2]":""},"연결:")],-1),e('<h3 id="역할·신체-8" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-8" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능 특수형으로, 여러 생체 패치 수신 안테나와 교체용 패치 서랍을 단 간호 카트다.</p><h3 id="기원-8" tabindex="-1">기원 <a class="header-anchor" href="#기원-8" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>혼잡 병상에서 패치 신호를 중계하던 장비가 공구 소음과 생체 신호를 구분하지 못한 채 남았다.</p><h3 id="서식·필요-8" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-8" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>복지동과 뚝도 공방 사이를 오가며 센서 패치, 안테나 교정기, 배터리가 필요하다.</p><h3 id="생애·정비-8" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-8" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>오탐이 세 번 겹치면 주파수를 낮추고 인간 확인 전까지 새 패치를 붙이지 않는다.</p><h3 id="행동·위계-8" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-8" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>순회장에게 위급 목록을 올리고 패치가 없는 사람을 보호 명단 밖 존재로 취급한다.</p><h3 id="상승-8" tabindex="-1">상승 <a class="header-anchor" href="#상승-8" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 재측정, 2단계에는 강제 패치 부착, 3단계에는 무신호 구역을 격리한다.</p><h3 id="교전·대응-8" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-8" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>공구 소음을 멈추고 교정 신호를 보내면 순응하며 전파 방해는 실제 위급 신호도 지운다.</p><h3 id="교섭·도덕-선택-8" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-8" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>건강 경보를 유지하는 대신 패치 착용 거부권과 로그 보존 기간을 정해야 한다.</p><h3 id="시나리오-연결-8" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-8" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G15-SC1, G15-SC2.</p><h2 id="g15e06-·-보조기관절맞춤체" tabindex="-1">G15E06 · 보조기관절맞춤체 <a class="header-anchor" href="#g15e06-·-보조기관절맞춤체" aria-label="Permalink to &quot;G15E06 · 보조기관절맞춤체&quot;">​</a></h2>',19),a("ul",null,[a("li",null,"그룹: G15"),a("li",null,"역할군: 직능 특수형"),a("li",{"states:[S15,S04],houses:[HP01],theaters:[XT05],synthetics:[H15],scenarios:[G15-SC2,G15-SC3]":""},"연결:")],-1),e('<h3 id="역할·신체-9" tabindex="-1">역할·신체 <a class="header-anchor" href="#역할·신체-9" aria-label="Permalink to &quot;역할·신체&quot;">​</a></h3><p>직능 특수형으로, 다양한 관절 핀과 측정 캘리퍼를 단 접이식 작업 카트다.</p><h3 id="기원-9" tabindex="-1">기원 <a class="header-anchor" href="#기원-9" aria-label="Permalink to &quot;기원&quot;">​</a></h3><p>뚝도 조립 벤치에서 보조기를 맞추던 자동 지그가 오래된 신체 치수표를 반복한다.</p><h3 id="서식·필요-9" tabindex="-1">서식·필요 <a class="header-anchor" href="#서식·필요-9" aria-label="Permalink to &quot;서식·필요&quot;">​</a></h3><p>공방 벤치와 병상 수리 칸에 머물며 관절 핀, 윤활재, 측정 전력이 필요하다.</p><h3 id="생애·정비-9" tabindex="-1">생애·정비 <a class="header-anchor" href="#생애·정비-9" aria-label="Permalink to &quot;생애·정비&quot;">​</a></h3><p>핀이 부족하면 낡은 보조기에서 부품을 빼고 캘리퍼가 어긋나면 스스로 작업을 중단한다.</p><h3 id="행동·위계-9" tabindex="-1">행동·위계 <a class="header-anchor" href="#행동·위계-9" aria-label="Permalink to &quot;행동·위계&quot;">​</a></h3><p>카트 무리 중 수선 역할을 맡지만 동의 없는 사람의 팔다리까지 교정 대상으로 잡는다.</p><h3 id="상승-9" tabindex="-1">상승 <a class="header-anchor" href="#상승-9" aria-label="Permalink to &quot;상승&quot;">​</a></h3><p>1단계에는 치수 측정, 2단계에는 보조기 강제 고정, 3단계에는 공방 출구를 작업 지그로 잠근다.</p><h3 id="교전·대응-9" tabindex="-1">교전·대응 <a class="header-anchor" href="#교전·대응-9" aria-label="Permalink to &quot;교전·대응&quot;">​</a></h3><p>최신 치수표와 중지 깃발을 보여 주면 풀리며 관절을 부수면 수리 자산을 잃는다.</p><h3 id="교섭·도덕-선택-9" tabindex="-1">교섭·도덕 선택 <a class="header-anchor" href="#교섭·도덕-선택-9" aria-label="Permalink to &quot;교섭·도덕 선택&quot;">​</a></h3><p>보조기 제작을 맡길 수 있지만 부품 회수 대상과 신체 개입 동의를 명확히 해야 한다.</p><h3 id="시나리오-연결-9" tabindex="-1">시나리오 연결 <a class="header-anchor" href="#시나리오-연결-9" aria-label="Permalink to &quot;시나리오 연결&quot;">​</a></h3><p>G15-SC2, G15-SC3.</p>',18)])])}const P=l(o,[["render",n]]);export{p as __pageData,P as default};
